/**
 * CallSuraksha AI — demo sample + comparison manifests (Phase 8).
 *
 * The manifests are generated by scripts/generate-samples.mjs and
 * scripts/add-noise.mjs and served as static JSON from public/. The Demo
 * and Compare pages fetch them at runtime — no sample data is hardcoded
 * in the frontend, so regenerating the audio updates the pages.
 *
 * Analysis results are cached in memory per sample (and per compare
 * recording) so a repeat click does NOT trigger another paid Gnani call.
 * A "Re-analyze" action clears the cache entry for a fresh call.
 */
import type { AnalysisResult } from './analysis'

export type DemoSample = {
  id: string
  title: string
  description: string
  category: string
  language: string
  languageLabel: string
  voice: string
  model: string
  script: string
  file: string
  durationSeconds: number
  bytes: number
  sha256: string
}

export type CompareManifest = {
  sourceSample: string
  referenceTranscript: string
  importantPhrases: string[]
  noise: {
    type: string
    targetSnrDb: number
    measuredSnrDb: number
    signalRms: number
    noiseRms: number
    method: string
  }
  clean: { file: string; durationSeconds: number; bytes: number }
  noisy: { file: string; durationSeconds: number; bytes: number; sha256: string }
}

export async function loadSampleManifest(): Promise<DemoSample[]> {
  const res = await fetch('/samples/manifest.json')
  if (!res.ok) throw new Error(`Samples manifest load nahi hui (HTTP ${res.status})`)
  const data = (await res.json()) as { samples: DemoSample[] }
  if (!Array.isArray(data.samples) || data.samples.length === 0) {
    throw new Error('Samples manifest khaali hai')
  }
  return data.samples
}

export async function loadCompareManifest(): Promise<CompareManifest> {
  const res = await fetch('/compare/manifest.json')
  if (!res.ok) throw new Error(`Compare manifest load nahi hui (HTTP ${res.status})`)
  return (await res.json()) as CompareManifest
}

// --- In-memory analysis cache (no DB, no localStorage) ---------------------
// The cache stores the result AND the time of the original API call, so a
// reused result keeps its original timestamp — it never looks like a fresh
// request. Repeat clicks reuse the cache; a fresh call happens only on
// Re-analyze / Re-run.
export type CachedAnalysis = { result: AnalysisResult; analyzedAt: string }
const analysisCache = new Map<string, CachedAnalysis>()

export function getCachedAnalysis(key: string): CachedAnalysis | undefined {
  return analysisCache.get(key)
}

export function setCachedAnalysis(key: string, result: AnalysisResult, analyzedAt: string): void {
  analysisCache.set(key, { result, analyzedAt })
}

export function clearCachedAnalysis(key: string): void {
  analysisCache.delete(key)
}
